5	/**
6	 * Rolls a date forward onto a business day: a Saturday or Sunday becomes the
7	 * following Monday, while a weekday is returned unchanged.
8	 */
9	public final class BusinessDay {
10	
11	    private BusinessDay() {
12	    }
13	
14	    public static LocalDate onOrAfter(LocalDate date) {
15	        int day = date.getDayOfWeek().getValue(); // Mon=1 .. Sun=7
16	        return day > 5 ? date.plusDays(8 - day) : date;
17	    }
